function portraitUrlOf(name) {
  if (!name) return '';
  var n = String(name).trim();
  if (PORTRAIT_URLS[n]) return PORTRAIT_URLS[n];
  var tail = n.split('·').pop().trim();
  if (PORTRAIT_URLS[tail]) return PORTRAIT_URLS[tail];
  /* ★ v445：最长键优先，别用「第一个命中的」。
     原来的写法是 `for (var k in ...) { if (命中) return }` ——
     而「古月」是「古月娜」的前缀，只要遍历先碰到「古月」，
     `古月娜·银龙王` 就会被配上**古月的图**。这是 v431 在 05 侧踩过的同款坑，
     引擎这份一直没同步。05 已经改成「收集全部命中 → 取最长」，这里照抄。 */
  var best = '', bestLen = -1;
  for (var k in PORTRAIT_URLS) {
    if (!PORTRAIT_URLS[k] || n.indexOf(k) === -1) continue;
    if (k.length > bestLen) { bestLen = k.length; best = PORTRAIT_URLS[k]; }
  }
  return best;
}

/* ═══ v445 · 立绘的**镜像回退**（引擎侧原本一条都没有）═══════════════════════
   病根：v442 给 `05-界面脚本.js` 加了 `xzImgAlt`/`xzImgRetry`（失败自动换镜像），
   但**引擎这份没加**。于是同一张图在状态栏能出来、在战斗中出不来 ——
   而战斗面板是全卡最显眼的地方，玩家只会说「立绘还是显示不了」。
   实测（--noproxy 直连，模拟国内）：fastly 8/8 全 301 跳 raw.githubusercontent.com，
   gcore 8/8 全 200。⇒ 光换域名解决了"这一次"，解决不了"下一次某个镜像挂了"。

   做法与 05 完全一致（**别在这里另发明一套**）：
     · `src` 先给 gcore 那条；`data-xz-src` 记当前实际用的那条；
     · `onerror` 里调 `portraitFallback(this)`，按 gcore → testingcf → cdn → fastly 往后找；
     · 全挂就 `this.remove()`（引擎原来的 `onerror="this.remove()"` 保留，见下面调用点）。
   ⚠ 为什么用**内联 onerror** 而不是 addEventListener：引擎这两处是拼字符串渲染、
     渲染完就没有节点钩子了（05 那边有 MutationObserver 兜底，引擎没有）。
     内联属性在酒馆 CSP 下对本项目一直是可用的（现有代码本来就写了 onerror）。
   ⚠ 环形只走一圈：`_XZ_PIC_TRIED` 记已试过的 host，防止两个镜像互相踢皮球。 */
var _XZ_PIC_HOSTS = ['gcore', 'testingcf', 'cdn', 'fastly'];

function portraitFallback(img) {
  try {
    if (!img) return;
    var cur = img.getAttribute('data-xz-src') || img.src || '';
    var m = /^https:\/\/(gcore|testingcf|cdn|fastly)\.jsdelivr\.net\/(.+)$/.exec(cur);
    if (!m) { if (img.parentNode) img.parentNode.removeChild(img); return; }
    var tried = (img.getAttribute('data-xz-tried') || '').split(',');
    if (tried.indexOf(m[1]) < 0) tried.push(m[1]);
    var rest = m[2], nxt = '';
    for (var i = 0; i < _XZ_PIC_HOSTS.length; i++) {
      var h = _XZ_PIC_HOSTS[i];
      if (tried.indexOf(h) >= 0) continue;
      nxt = 'https://' + h + '.jsdelivr.net/' + rest;
      break;
    }
    if (!nxt) { if (img.parentNode) img.parentNode.removeChild(img); return; }
    img.setAttribute('data-xz-tried', tried.join(','));
    img.setAttribute('data-xz-src', nxt);
    img.src = nxt;
  } catch (e) {
    try { if (img && img.parentNode) img.parentNode.removeChild(img); } catch (e2) {}
  }
}

/* 拼 <img> 的统一入口 —— 两处渲染点都走它，免得将来又只改一处。
   `onerror` 里同时做两件事：先试镜像，全挂了才 remove。
   （原来只有 `this.remove()`：镜像一挂就直接留空白，连第二次机会都没有。） */
function portraitImgTag(url, cls, extra) {
  if (!url) return '';
  return '<img class="' + cls + '" src="' + esc(url) + '"'
    + ' data-xz-src="' + esc(url) + '" alt="" loading="lazy"'
    + (extra ? (' ' + extra) : '')
    + ' onerror="portraitFallback(this)">';
}

/* ═══ v435 · 人名与玄技名的**唯一规范化入口** ═══════════════════════════
   用户原话（2026-10-28）：
     「人物名字也他妈生成不规范，禁止生成前缀后缀，只能生成人名，
       萧诀就是萧诀，而不是剑修·萧诀。」
     「玄技的名字生成不规范，剑系技能只能这样生成：剑系·xxxx，
       然后剑系特效就识别这个剑系。」

   ── 为什么要在**读入**时就削，而不是只求模型写对 ────────────────────
   模型写「剑修·萧诀」有现实原因：正文里需要交代这个人什么路数。
   只要它还这么写，玩家就一定会看到「剑修·萧诀 用 一剑断江 攻击了 剑修·萧诀」
   —— 战斗界面是全卡最密的信息界面，这类前缀在战报里会被放大成噪音。
   所以两道一起做：① 世界书里写死规矩；② 这里做兜底削除（模型不听话也不至于难看）。
   ⚠ 削除只发生在**战斗显示层**（fighter 构建 + 名单解析），
     绝不回写变量 —— 变量里的键名是存档主键，改了就把人物档案弄丢了。 */

/* 人名前缀黑名单：职业/身份/势力/称号。
   ⚠ 只匹配「两个字以上 + 中点」的形状，单字前缀一律不动
     （「白·素贞」这种写法不存在，误削风险大于收益）。 */
var XZ_NAME_PREFIX_RE = /^(?:剑修|刀修|枪修|拳修|体修|术修|符修|丹修|器修|阵修|魔修|妖修|鬼修|儒修|佛修|道修|散修|剑客|刀客|剑仙|刀圣|剑圣|真人|道人|上人|长老|执事|弟子|内门|外门|真传|亲传|首席|大天骄|天骄|圣女|圣子|宗主|门主|阁主|族长|城主|山主|宫主|殿下|公子|姑娘|前辈|道友|散人|居士|掌柜|教习|护法|堂主|舵主|杀手|佣兵|护卫|队长|首领|大王|妖王|魔王|少主|公子爷|少爷|小姐|阁下|陛下|师尊|师兄|师姐|师弟|师妹)\s*[·・‧∙]\s*/;

/* 玄技名的「剑系·」族：这是**唯一被承认的剑系标记**（用户 2026-10-28 定）。
   以前剑系判定是「名字里含『剑』字」—— 于是「万剑归宗」「剑指苍穹」都算剑系，
   而真正的剑招只要名字不带剑（「霜落」）就吃不到剑弧。改成认前缀之后：
     · 「剑系·一剑断江」「剑系·霜落」→ 剑系特效
     · 「万剑归宗」「剑指苍穹」      → 不认（除非也写前缀）
   兼容保留：不带前缀但**以剑/刀/枪起头**的老存档仍按剑系处理，
   否则老档一更新特效就全没了（这条是过渡，别当成规范）。 */
var XZ_SWORD_TAG = '剑系·';
function xzSkillIsSword(name) {
  var s = String(name == null ? '' : name);
  if (!s) return false;
  if (s.indexOf(XZ_SWORD_TAG) === 0) return true;
  /* 前缀写法不统一时（「剑系 · X」「剑系.X」「［剑系］X」）也认，但只在**开头**认。 */
  if (/^[\s\[【（(]*剑系\s*[·・‧∙.。]\s*\S/.test(s)) return true;
  if (/^[\s\[【（(]*剑系[\s\]】）)]/.test(s)) return true;
  /* 过渡兼容：以剑起头（剑法/剑诀/剑意…），以及老写法「XX剑法」以外的剑字开头 */
  if (/^\s*剑/.test(s)) return true;
  return false;
}
/* 把人名里的身份前缀削掉：`剑修·萧诀` → `萧诀`。
   ★ 只削**开头**那一段，且必须是黑名单里的词 —— 「萧·诀」这种不会被碰。
   ★ 削完为空（比如整串就是一个「剑修·」）就原样返回，宁可难看也不返回空名。 */
function xzCleanPersonName(name) {
  var s = String(name == null ? '' : name).replace(/[\u3000]/g, ' ').trim();
  if (!s) return s;
  /* 全角/半角括号包着的身份也削：`【剑修】萧诀` */
  s = s.replace(/^[\[【（(]\s*(?:剑修|刀修|枪修|拳修|体修|术修|符修|丹修|魔修|妖修|散修|剑客|剑仙|剑圣|刀圣|真人|道人|长老|弟子|真传|天骄|圣女|圣子|宗主|门主|阁主|城主|公子|姑娘|前辈|道友)\s*[\]】）)]\s*/, '');
  s = s.replace(XZ_NAME_PREFIX_RE, '');
  s = s.trim();
  return s || String(name).trim();
}
/* 玄技名规范化：把各种「剑」写法统一成 `剑系·原名`。
   ★ 只做**前缀归一**，不动原名的字 —— 「一剑断江」不许被改写成「剑系·剑」那种。
   ★ 已经带前缀的原样返回（幂等），所以可以被反复调用。 */
function xzCleanSkillName(name) {
  var s = String(name == null ? '' : name).replace(/[\u3000]/g, ' ').trim();
  if (!s) return s;
  /* 已经是规范写法 → 不动 */
  if (s.indexOf(XZ_SWORD_TAG) === 0) return s;
  /* 「剑系 · X」「剑系.X」「剑系X」→ 统一成「剑系·X」 */
  var m = /^\[?【?\(?（?\s*剑系\s*[·・‧∙.。]?\s*([\s\S]+?)\s*\]?】?\)?）?$/.exec(s);
  if (m && m[1]) return XZ_SWORD_TAG + m[1];
  /* 老写法「剑法·X」「剑诀·X」→ 剑系·X（同一个族，不该在卡面上出现两种前缀） */
  var m2 = /^\[?【?\(?（?\s*(?:剑法|剑诀|剑术|剑道|剑意)\s*[·・‧∙.。]\s*([\s\S]+?)\s*\]?】?\)?）?$/.exec(s);
  if (m2 && m2[1]) return XZ_SWORD_TAG + m2[1];
  /* 不带任何前缀、但确实是剑招（以剑起头）→ 补前缀 */
  if (/^\s*剑/.test(s)) return XZ_SWORD_TAG + s;
  return s;
}

// 法相投影台：全场只此一块，统一挂在对方（敌方栏）上方。
// 轮到谁就换谁的立绘；没立绘就显示一个大问号。
/* ===== v41 九州玄幻 · 境界系数（十二境 48 档）=====
   引玄 → 凝府 → 玄枢 → 化域 → 尊玄 → 穹境 → 玄罡 → 玄王 → 玄皇 → 玄宗 → 玄圣 → 帝境
   每境四档，第 4 档是「巅峰档」，各有专称（大凝府 / 大玄枢 / … / 穹主；引玄无专称，就叫引玄巅峰）。
   跨度 1.00 → 17.92（v40 是 1.00 → 6.55）：**跨大境界 ×1.15，同境内每小档 ×1.04**。
   穹境（第 6 境）是「当世明面绝顶」——天剑阁门主、各大势力之主都在这一层；
   其上六境（玄罡 ~ 帝境）是**传说境**：上古遗留、隐世老祖、浩劫之源。帝境巅峰「玄帝」是传说级天花板。
   表尾的旧境界名（炼气/筑基/金丹/元婴/化神）是**旧档兼容**：老存档不报错、不掉档。 */
