function xzCombCount(a, b) {
  if (b < 0 || b > a) return 0; b = Math.min(b, a - b);
  var r = 1; for (var i = 1; i <= b; i++) r = r * (a - b + i) / i; return Math.round(r);
}
/* ★ v94：04 自己也要按招式名查位次（xzTypeOf / 骨架兜底都读它），
   而 `xzPosOf` 原本只定义在 05 ⇒ 跨脚本悬空引用，一调就抛、被空 catch 吞掉。
   04 手里本来就有自己的 SKILL_LOADS（2675 行那份），直接就地建表，与 05 同源同逻辑。 */
var XZ_POS_OF = {}, XZ_POS_BUILT = false;
function xzPosOf(name) {
  if (!XZ_POS_BUILT) {
    XZ_POS_BUILT = true;
    try { (typeof SKILL_LOADS !== 'undefined' ? SKILL_LOADS : []).forEach(function (g) {
      (g.items || []).forEach(function (it) { if (it && it.name) XZ_POS_OF[it.name] = it.pos || ''; });
    }); } catch (ePos) {}
  }
  return XZ_POS_OF[String(name || '')] || '';
}
