      if (_hpKSum > 0 && !_hpFromVar) maxHp = Math.round(maxHp * (1 + Math.min(0.30, _hpKSum)));
      if (_mpKSum > 0 && !_mpFromVar) maxMp = Math.round(maxMp * (1 + Math.min(0.30, _mpKSum)));
