function afterTurnExecuted(actor) {
  if (actor) {
    if (actor._pullForwardDistance) {
      xzTrackSet(actor, actor._pullForwardDistance);
      actor._pullForwardDistance = null;
      // 【守株】：敌方自拉条时，带【守株】者跟着拉条 100
      var stFoes = actor.side === 'ally' ? BattleState.enemies : BattleState.allies;
      stFoes.forEach(function(e) {
        if (e.alive && e.passive && e.passive.effects.indexOf('守株') !== -1) {
          xzTrackAdd(e, 100);
          BattleState.logs.push('<span style="color:#84cc16">【守株】借机自拉条！</span>');
        }
      });
    } else {
      /* ⚠ v29：行动条的消耗**已经由内核 XZTurn.settle() 统一负责**（那才是唯一出口）。
         这里故意不再扣条 —— 两处都扣会扣掉两倍进度，直接把保底手数打回原形。
         本函数只负责「出手之后额外要做的事」：拉条（_pullForwardDistance）与【守株】联动。
         （契约：条的唯一所有者在 settle；谁都别在这里加第二次扣除。） */
    }
  }
  BattleState.currentFighterId = null;
  BattleState.awaitingActorId = null;
  BattleState.pendingAction = { type: 'attack' };
  BattleState.selectedTargets = [];
  BattleState.activeOtherMenu = false;
  if (!checkEndCondition()) { stopTickLoop(); advanceTimelineTick(TickLoop.gen); }
}

