  if (coef < 1.0) coef = 1.0;
  if (coef > 2.5) coef = 2.5;

  var style = String(d.流派 !== undefined && d.流派 !== null ? d.流派 : (d.风格 !== undefined && d.风格 !== null ? d.风格 : '通用')).trim() || '通用';
  var wantAoe = (d.攻击类型 === '范围' || (_t && _t.攻击类型 === '范围'));
