    '@keyframes xzDvSparkLite{0%{opacity:0;transform:scale(.4)}12%{opacity:1}100%{opacity:0;transform:scale(.85)}}',
  '@keyframes xzDvSpark{0%{opacity:0;transform:translate(-50%,-50%) scale(.4)}12%{opacity:1}100%{opacity:0;transform:translate(calc(-50% + var(--dx)),calc(-50% + var(--dy))) scale(var(--sc))}}',
    '@keyframes xzDvComet{0%{opacity:0;transform:translate(0,0) scale(.5)}10%{opacity:1}100%{opacity:0;transform:translate(var(--cx),var(--cy)) scale(1.15)}}',
