      requestAnimationFrame(function () {
        requestAnimationFrame(function () { try { frame.classList.add('xz-dv-shake'); } catch (e0) {} });
      });
      setTimeout(function () { try { frame.classList.remove('xz-dv-shake'); } catch (e1) {} }, 760);
