  '提速': { kind: '常驻增益', beh: 'buff', sub: 'haste' },  '速度': { kind: '常驻增益', beh: 'buff', sub: 'haste' },
  '暴击': { kind: '常驻增益', beh: 'buff', sub: 'crit' },
