function petBridgeFeed(name, itemKey) {
  try {
    if (!name) return { ok: false, msg: '未指定灵宠' };
    var vars = readMvuVars();
    var z = vars.主角信息 || (vars.主角信息 = {});
    var pets = z.灵宠 || null;
    if (!pets || !pets[name]) return { ok: false, msg: '没有名叫「' + name + '」的灵宠' };
    var bag = vars.背包 || null;
    var picked = null, pickedKey = '';
    if (bag && typeof bag === 'object') {
      if (itemKey && bag[itemKey]) {
        picked = bag[itemKey]; pickedKey = itemKey;   // 玩家在面板里选的那一件
      } else if (!itemKey) {
        for (var k in bag) {
          var it0 = bag[k] || {};
          if (Number(it0.数量 || 0) <= 0) continue;
          var nm0 = String(it0.物品名称 || k);
          var tp0 = String(it0.类型 || '');
          if (tp0 === '丹药' || tp0 === '材料' || /[丹草果肉髓露蜜饼米]/.test(nm0)) { picked = it0; pickedKey = k; break; }
        }
      }
    }
    if (!picked) return { ok: false, msg: itemKey ? '背包里没有这一件，或已被吃完' : '背包里没有可喂的丹药或灵物' };
    if (Number(picked.数量 || 0) <= 0) return { ok: false, msg: '这一件已经吃完了' };
    var itemName = String(picked.物品名称 || pickedKey);
    var gain = petFeedGainOf(picked.品质);                      // 黄 5 / 玄 20 / 地 50 / 天 100 / 神 100
    var before = petSatietyOf(pets[name]);
    var after = Math.max(0, Math.min(100, before + gain));
    var left = Number(picked.数量 || 1) - 1;
    pets[name].饱食度 = after;
    if (left <= 0) delete bag[pickedKey]; else picked.数量 = left;
    writeMvuVars(vars);
    var back = readMvuVars();
    var bz = (back.主角信息 && back.主角信息.灵宠 && back.主角信息.灵宠[name]) || {};
    if (Number(bz.饱食度) !== after) throw new Error('回读校验失败：饱食度未写入');
    var tier = petSatietyTier({ 饱食度: after });
    return {
      ok: true, satiety: after, gain: gain, hpRate: tier.rate,
      msg: '喂下『' + itemName + '』（' + (picked.品质 || '黄阶') + '）：【' + name + '】饱食度 ' + before + ' → ' + after + '（' + tier.label + '·登场 ' + Math.round(tier.rate * 100) + '% 血）'
    };
  } catch (e) {
    log('灵宠喂食失败', e);
    return { ok: false, msg: '写入失败：' + errMsg(e) };
  }
}
