function exposePetBridge() {
  var api = { version: '1.3', listPets: petBridgeList, togglePet: petBridgeToggle, feedPet: petBridgeFeed, feedables: petBridgeFeedables, transformPet: petBridgeTransform, releasePet: petBridgeRelease, deleteBagItem: bridgeDeleteBagItem, deleteLearned: bridgeDeleteLearned, deletePerson: bridgeDeletePerson };
  try { window.__XIUXIAN_ATB_BRIDGE__ = api; } catch (e) {}
  try { if (window.parent && window.parent !== window) window.parent.__XIUXIAN_ATB_BRIDGE__ = api; } catch (e) {}
  try { if (window.top && window.top !== window) window.top.__XIUXIAN_ATB_BRIDGE__ = api; } catch (e) {}
  try { if (HOST && HOST !== window) HOST.__XIUXIAN_ATB_BRIDGE__ = api; } catch (e) {}
  log('灵宠管理桥已挂载（状态栏【灵宠】页可用；删除类：放生灵宠 / 丢弃物品 / 遗忘本领 / 移除角色）');
  return api;
}

/* ★★★ v298（用户 2026-10-21，截图）：注入酒馆的战报里露出裸标签 ——
   `造成 <b class="xiuxian_timeline_atb-nb xiuxian_timeline_atb-nb-dmg">119</b> 伤害`。
   根因：战报正文里的数字被 `<b class="…-nb">` 包着（那是**界面用的圆角小框**，
   由 v234 的 `_nbBox` 拼进 `push()` 的文本里），而 `S.log[].t` 是**同一份字符串**：
   界面渲染时它被 `_ma` 正则重新解析、重建成小框（所以界面上好看），
   但注入正文时只是 `+ ev +`，HTML 就原样吐进小说里了。
   ⇒ 两处一起修：`push()` 时把攻击行的标签剥掉（界面反正会重建），
     生成战报时再兜一次底（名字、buff 文本也可能带标签）。
   ⚠ 只剥标签、**反转义实体**，不碰中文标点与换行 —— 战报要能直接读。 */
function xzPlainText(v) {
  var s = String(v == null ? '' : v);
  if (!s) return '';
  s = s.replace(/<br\s*\/?>/gi, ' ');
  s = s.replace(/<[^>]*>/g, '');
  s = s.replace(/&nbsp;/g, ' ')
       .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
       .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
       .replace(/&amp;/g, '&');
  return s;
}

function generateBattleReport() {
  /* ★ v77：原函数开头按 hpRate 算一个 `伤势状态`（健康/轻伤/重伤）写进战报，
     字段已废除 —— 改为直接把剩余气血与占比写进战报，信息更准也更省事。
     （标签与数值两套口径必然会漂移，这正是本项目反复踩的坑。） */
  var p = BattleState.allies.find(function(a){ return a.isPlayer; });
  var hpNote = (p && p.maxHp) ? ('气血余 ' + Math.max(0, Math.round(p.hp)) + '/' + Math.round(p.maxHp) + '（' + Math.round(Math.max(0, p.hp) / p.maxHp * 100) + '%）') : '';

  var rw = BattleState.resultWrite || null;
  if (!hpNote && rw && rw.hpRate != null) hpNote = ('气血余 ' + (rw.hpLeft || 0) + '（' + Math.round((rw.hpRate || 0) * 100) + '%）');

  var resultTitle = BattleState.result === 'win' ? '【斗法大捷】' : '【斗法受挫】';
  var allyStr = BattleState.allies.map(function(a){ return a.name + '(' + a.realm + '·' + a.element + '玄元属性·武器:' + a.artifact.name + (a.weaponType && a.weaponType !== '无' ? ('/' + a.weaponType) : '/徒手') + (a.tianjiao ? ('·' + a.tianjiaoName) : '') + (a.faction ? ('·' + a.faction) : '') + (a.isPet ? '·灵宠' : '') + ')'; }).join('、');
  var enemyStr = BattleState.enemies.map(function(e){ return e.name + '(' + e.realm + '·' + e.element + '玄元属性' + (e.weaponType && e.weaponType !== '无' ? ('·' + e.weaponType) : '·徒手') + (e.tianjiao ? ('·' + e.tianjiaoName) : '') + (e.faction ? ('·' + e.faction) : '') + (e.isPet ? '·灵宠' : '') + ')'; }).join('、');

  var plotGuide = BattleState.decision.storyMode === 'skip' ? '【剧情推演引导】：跳过漫长战斗招式描写，一笔带过战斗过程，直接承接战斗结果推进后续。' : '【剧情推演引导】：详尽描绘斗法交锋过程，承接招式机锋推演后续波澜。';
  var fateGuide = BattleState.decision.mercyMode === 'kill' ? '【战败敌方处置】：杀伐果断，尽数斩草除根、身死道消。' : '【战败敌方处置】：留手存命，饶其性命或予以禁锢收押。';

  var skillUsageList = [];
  for (var skName in BattleState.userSkillUsageCount) {
    skillUsageList.push(skName + ' x' + BattleState.userSkillUsageCount[skName] + '次');
  }
  var skillUsageStr = skillUsageList.length ? skillUsageList.join('、') : '无';

  var s = '<战斗结算>\n' +
    (hpNote ? (hpNote + '\n') : '') +
    resultTitle + '\n' +
    plotGuide + '\n' +
    fateGuide + '\n' +
    '对阵双方：我方【' + allyStr + '】 VS 敌方【' + enemyStr + '】\n' +
    '激战时辰：交锋 ' + BattleState.round + ' 轮 (天地时序 ' + BattleState.tickCount + ' 息)\n' +
    '主角出招统计：' + skillUsageStr + '\n' +
    '最终斩杀玄技：【' + BattleState.userLastFatalSkill + '】\n\n' +
    '【威能输出统计】\n';

  BattleState.allies.forEach(function(a) {
    s += '· 我方 ' + a.name + '：累计造成 ' + (a.totalDamageDealt || 0) + ' 点斗法伤害' + ((a.totalShieldAbsorbed || 0) > 0 ? ('，护盾吸收了 ' + a.totalShieldAbsorbed + ' 点伤害') : '') + '\n';
  });
  BattleState.enemies.forEach(function(e) {
    s += '· 敌方 ' + e.name + '：累计造成 ' + (e.totalDamageDealt || 0) + ' 点斗法伤害' + ((e.totalShieldAbsorbed || 0) > 0 ? ('，护盾吸收了 ' + e.totalShieldAbsorbed + ' 点伤害') : '') + '\n';
  });

  // ===== 脚本已直接写入变量的结算数据（模型不得再改这些字段）=====
  s += '\n【脚本已直接写入变量，模型禁止在 <UpdateVariable> 里重写以下字段】\n';
  /* ★ v77：原来这里钉的是「· 伤势状态：健康/轻伤/重伤」。
     字段已废除，改钉气血口径：战后气血由正文更新按剧情写入，脚本不代写。 */
  s += '· 气血：本战结束时余 ' + (hpNote || '气血未知') + '（脚本不写该字段，按剧情结算后由正文更新写入）\n';
  if (rw && rw.applied && rw.applied.ok) {
    s += '· 经验值：本战不产经验（定调：经验与境界只由修炼产生——玄诀品阶 × 玄元级别，见《变量更新细则》；模型自行按该档位写入，不在战报里结算）\n';
    var profLines = [];
    (rw.profGains || []).forEach(function (g) {
      if (g.skipped) { profLines.push((g.name || '（未标）') + '（不在表内，无路可归，未写入）'); return; }
      if (g.gain > 0) profLines.push(daoLabelOf(g.dao) + ' +' + g.gain + ' → ' + g.after + '（' + g.level + '）');
    });
    if (rw.heartProf && rw.heartProf.gain > 0) {
      profLines.push('玄诀《' + rw.heartProf.name + '》计入' + daoLabelOf(rw.heartProf.dao) + ' +' + rw.heartProf.gain + ' → ' + rw.heartProf.after + '（' + rw.heartProf.level + '）');
    }
    if (rw.divineProf) {
      if (rw.divineProf.skipped) profLines.push('神通《' + rw.divineProf.name + '》（不在表内，无路可归，未写入）');
      else if (rw.divineProf.gain > 0) profLines.push('神通《' + rw.divineProf.name + '》计入' + daoLabelOf(rw.divineProf.dao) + ' +' + rw.divineProf.gain + ' → ' + rw.divineProf.after + '（' + rw.divineProf.level + '）');
    }
    if (rw.pet || (rw.pets && rw.pets.length)) {
      (rw.pets || [rw.pet]).forEach(function (pe) {
        s += '· 灵宠【' + pe.name + '】：饱食度 ' + pe.satBefore + ' → ' + pe.satAfter + '（战斗消耗 -' + PET_SATIETY_DECAY + '）\n';
      });
    }
  } else {
    s += '· 伤势写回变量未成功（' + ((rw && rw.applied && rw.applied.err) || '未知原因') + '），请提醒玩家查看斗法台与控制台。\n';
  }
  s += '· 模型只需把 `战斗状态` 置回 false（若脚本已关闭就不必再写）；以上伤势 / 灵宠成长值均已由斗法器写入，正文不要再算一遍、也不要写进变量更新块；**经验值与境界不在此列**（战斗不产经验，只按修炼档位写）。\n';
  s += '· 天骄压制：非天骄攻击天骄时伤害 −10%（普通天骄）/ −20%（大天骄）/ −35%（天选之子），已计入上述伤害；天骄打非天骄无额外加成。★ 它是**最后一环乘区**：增伤/减伤/破防/暴击算完后再打折，所以明细里那个『受××压制 -X%』是真扣掉的、不是摆设。\n';
  s += '· 流派与兵器（严格对口）：剑法宜持剑、刀法宜持刀、枪法宜持枪、特殊法宜持特殊法器（剑刀枪之外的兵器）；体术与纯法宜徒手（v43：皆非强制）。★ v43 起武器**不再禁招**：兵器不对口照样能放（只是吃不到兵器那一路的加成），正文不要再写“使不出来”。\n';
  var ov = BattleState.sideOverflow;
  if (ov && ((ov.ally && ov.ally.length) || (ov.enemy && ov.enemy.length))) {
    s += '· 阵位上限：每方最多九人、全场十八人。';
    if (ov.ally && ov.ally.length) s += '我方候场【' + ov.ally.join('、') + '】（可写作外围掠阵、未及入场）';
    if (ov.enemy && ov.enemy.length) s += '敌方候场【' + ov.enemy.join('、') + '】';
    if (ov.npcPets && ov.npcPets.length) s += '灵宠未入场【' + ov.npcPets.join('、') + '】';
    s += '\n';
  }

  s += '\n【关键交锋机锋】\n';
  BattleState.keyEvents.forEach(function(ev) { s += '· ' + xzPlainText(ev) + '\n'; });
  s += '后续剧情请严格承接以上结算推演。\n</战斗结算>';
  return s;
}

function fillToInput(text) {
  try {
    // 注入战报的同时，脚本顺手把「战斗状态」关掉（模型那侧不会再重复写；回读校验一下）
    var closedBattle = false;
    var closeErr = '';
    try {
      var vars = readMvuVars();
      if (vars.战斗状态 !== false) {
        vars.战斗状态 = false;
        writeMvuVars(vars);
        var back = readMvuVars();
        if (back.战斗状态 !== false) throw new Error('回读校验失败：战斗状态仍为 ' + back.战斗状态);
        closedBattle = true;
      } else {
        closedBattle = true;
      }
    } catch (eClose) { closeErr = errMsg(eClose); log('关闭战斗状态失败', eClose); }

    var doc = getDoc();
    var ta = doc.querySelector('#send_textarea');
    var tail = closedBattle ? '，并已把「战斗状态」置回 false' : ('（注意：战斗状态未关闭：' + closeErr + '）');
    if (ta) {
      ta.value = text;
      ta.dispatchEvent(new Event('input', { bubbles: true }));
      toast('斗法战报已注入输入栏' + tail + '！', closedBattle ? 'success' : 'warn');
      closePanel();
    } else {
      navigator.clipboard.writeText(text);
      toast('战报已复制至剪贴板' + tail + '！', 'info');
      closePanel();
    }
  } catch (e) { toast('填入失败', 'err'); }
}

