      name: String(c.姓名 || c.name || _nmStr),
      /* ★ v45：境界名归一 —— 人物列表里的写法（旧名/专称/缺档）与主角同口径收敛，
         否则「勾选的同伴」会带着一个查不中表的境界名进战斗，数值直接掉到兜底档。 */
      realm: xzNormRealmName(String(c.境界 || c.realm || '引玄初期')),
