          _s += chip('减伤值', _pct(_dr), _dr > 0 ? '#8fe0c4' : '#8a949e');
          _s += chip('增伤值', (_up >= 0 ? '+' : '') + _pct(_up), _up > 0 ? '#ffb3a7' : (_up < 0 ? '#8fe0c4' : '#8a949e'));
          /* 闪避值不是百分比 —— 它是 d20 上的「点数」（封顶 15），口径见 xzEvadeValueOf */
