    try {
      var v = readMvuVars();
      if (v && v.战斗状态 !== false) { v.战斗状态 = false; writeMvuVars(v); }
    } catch (eV) {}

    var ov = q('overlay');
    xzOverlayHide(ov);
    xzScrollRestore();
